pipeline {
    agent any

    environment {
        NODE_ENV = 'production'
        DOCKER_IMAGE = 'myapp:${BUILD_NUMBER}'
    }

    stages {
        stage('Checkout') {
            steps {
                checkout scm
            }
        }
        stage('Build') {
            steps {
                sh 'npm install'
                sh 'npm run build'
            }
        }
        stage('Test') {
            steps {
                sh 'npm test'
            }
            post {
                always {
                    junit '**/test-results.xml'
                    archiveArtifacts artifacts: 'dist/**', fingerprint: true
                }
            }
        }
        stage('Build Image') {
            steps {
                script {
                    docker.build(DOCKER_IMAGE)
                }
            }
        }
        stage('Push to Registry') {
            steps {
                script {
                    docker.withRegistry('https://registry.hub.docker.com', 'docker-hub')
                    docker.image(DOCKER_IMAGE).push()
                }
            }
        }
        stage('Deploy') {
            steps {
                sh './deploy.sh'
            }
        }
    }

    post {
        always {
            cleanWs()
        }
        success {
            echo 'Pipeline succeeded!'
        }
        failure {
            echo 'Pipeline failed!'
            mail to: 'team@example.com', subject: 'Build Failed', body: 'See ${BUILD_URL}'
        }
    }
}

pipeline {
    agent none

    stages {
        stage('Build') {
            agent any
            steps { sh 'npm run build' }
        }
        stage('Docker Build') {
            agent { label 'docker' }
            steps { sh 'docker build -t myapp .' }
        }
    }
}

stage('Test') {
    parallel {
        stage('Unit Tests') { steps { sh 'npm run test:unit' } }
        stage('Integration') { steps { sh 'npm run test:integration' } }
    }
}

stage('Deploy to Prod') {
    when {
        branch 'main'
        environment name: 'DEPLOY_PROD', value: 'true'
    }
    steps {
        sh './deploy.sh'
    }
}
